// 금융위원회 보도자료 목록에서 당일 등록건 추출
const html = $input.first().json.data;
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));
const year = koreaTime.getFullYear();
const month = String(koreaTime.getMonth() + 1).padStart(2, '0');
const day = String(koreaTime.getDate()).padStart(2, '0');
const todayStr = `${year}.${month}.${day}`;
const todayDash = `${year}-${month}-${day}`;

const items = [];

// FSC 사이트의 게시물 목록 파싱
// 테이블 행 단위로 처리
const rowPattern = /<tr[^>]*>(.*?)<\/tr>/gs;
let match;
while ((match = rowPattern.exec(html)) !== null) {
  const row = match[1];
  // 당일 날짜가 포함된 행만
  if (row.includes(todayStr) || row.includes(todayDash)) {
    const idMatch = /noticeId=(\d+)/.exec(row);
    const titleMatch = /<a[^>]*>(.*?)<\/a>/s.exec(row);
    if (idMatch && titleMatch) {
      items.push({
        json: {
          noticeId: idMatch[1],
          title: titleMatch[1].replace(/<[^>]*>/g, '').trim(),
          date: todayDash,
          url: `https://www.fsc.go.kr/no010101/view?noticeId=${idMatch[1]}`,
          source: '금융위원회',
          type: 'government_policy'
        }
      });
    }
  }
}

// 목록 형태가 다를 수 있으므로 li/div 패턴도 시도
if (items.length === 0) {
  const listPattern = /<a[^>]*href="[^"]*noticeId=(\d+)"[^>]*>(.*?)<\/a>/gs;
  const dateCheckPattern = new RegExp(`(${todayStr}|${todayDash})`);
  // 전체 HTML을 섹션으로 나누어 날짜 체크
  const sections = html.split(/<\/li>|<\/tr>/);
  for (const section of sections) {
    if (dateCheckPattern.test(section)) {
      const linkMatch = /noticeId=(\d+)/.exec(section);
      const textMatch = /<a[^>]*>(.*?)<\/a>/s.exec(section);
      if (linkMatch && textMatch) {
        const title = textMatch[1].replace(/<[^>]*>/g, '').trim();
        if (title && !items.find(i => i.json.noticeId === linkMatch[1])) {
          items.push({
            json: {
              noticeId: linkMatch[1],
              title: title,
              date: todayDash,
              url: `https://www.fsc.go.kr/no010101/view?noticeId=${linkMatch[1]}`,
              source: '금융위원회',
              type: 'government_policy'
            }
          });
        }
      }
    }
  }
}

if (items.length === 0) {
  return [{ json: { noData: true, type: 'government_policy', message: '오늘 등록된 금융위 보도자료 없음' } }];
}

return items;

// 상세 페이지에서 PDF 첨부파일 URL 추출 및 본문 요약
const html = $input.first().json.data || '';
const prevData = $('FSC 데이터 존재?').first().json;

// PDF 링크 추출
const pdfLinks = [];
// href에 .pdf가 포함된 링크
const pdfPattern = /href="([^"]*\.pdf[^"]*)"/gi;
let m;
while ((m = pdfPattern.exec(html)) !== null) {
  let url = m[1];
  if (!url.startsWith('http')) url = 'https://www.fsc.go.kr' + url;
  pdfLinks.push(url);
}
// 파일 다운로드 패턴
const dlPattern = /\/cmm\/fms\/FileDown\.do\?[^"'\s]*/gi;
while ((m = dlPattern.exec(html)) !== null) {
  pdfLinks.push('https://www.fsc.go.kr' + m[0]);
}
// atchFileId 패턴
const atchPattern = /fn_egov_downFile\(['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\)/gi;
while ((m = atchPattern.exec(html)) !== null) {
  pdfLinks.push(`https://www.fsc.go.kr/cmm/fms/FileDown.do?atchFileId=${m[1]}&fileSn=${m[2]}`);
}

// 본문 내용 추출
let content = '';
const contentPatterns = [
  /<div[^>]*class="[^"]*view[_-]?con[^"]*"[^>]*>(.*?)<\/div>/s,
  /<div[^>]*class="[^"]*board[_-]?con[^"]*"[^>]*>(.*?)<\/div>/s,
  /<td[^>]*class="[^"]*content[^"]*"[^>]*>(.*?)<\/td>/s
];
for (const pat of contentPatterns) {
  const cm = pat.exec(html);
  if (cm) {
    content = cm[1].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    break;
  }
}
if (content.length > 500) content = content.substring(0, 500) + '...';

return [{
  json: {
    noticeId: prevData.noticeId,
    title: prevData.title,
    date: prevData.date,
    url: prevData.url,
    source: '금융위원회',
    type: 'government_policy',
    content: content,
    pdfUrls: [...new Set(pdfLinks)],
    pdfCount: [...new Set(pdfLinks)].length
  }
}];

// PDF URL을 개별 아이템으로 분리
const item = $input.first().json;
return item.pdfUrls.map((url, i) => ({
  json: {
    ...item,
    pdfUrl: url,
    pdfIndex: i + 1,
    fileName: `FSC_${item.date}_${item.noticeId}_${i+1}.pdf`
  }
}));

// 이미 발송된 정책 제외 (중복 발송 방지)
const savedPolicies = $('구글시트 정부정책 저장').all();
const sentHistory = $('정부정책 발송내역 조회').all();

const sentTitles = new Set();
for (const item of sentHistory) {
  if (item.json.제목) sentTitles.add(item.json.제목.trim());
}

const newPolicies = [];
for (const item of savedPolicies) {
  const title = (item.json.title || item.json.제목 || '').trim();
  if (title && !sentTitles.has(title)) {
    newPolicies.push({
      json: {
        title: title,
        content: item.json.content || item.json.내용요약 || '',
        url: item.json.url || item.json.원문링크 || '',
        date: item.json.date || item.json.날짜 || '',
        pdfCount: item.json.pdfCount || item.json.PDF파일수 || 0,
        source: '금융위원회',
        type: 'government_policy'
      }
    });
  }
}

if (newPolicies.length === 0) {
  return [{ json: { noData: true, type: 'government_policy', policies: [], count: 0 } }];
}

return [{ json: { type: 'government_policy', policies: newPolicies.map(p => p.json), count: newPolicies.length } }];

// 네이버 뉴스 수집 기간 설정: 전날 06:30 ~ 당일 06:30
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));

// 당일 06:30 KST
const endTime = new Date(koreaTime);
endTime.setHours(6, 30, 0, 0);

// 전날 06:30 KST
const startTime = new Date(endTime);
startTime.setDate(startTime.getDate() - 1);

// 검색 키워드 목록
const keywords = ['펀드', '공모펀드', 'ETF 자산운용', '금융투자 펀드'];

return keywords.map(kw => ({
  json: {
    keyword: kw,
    startTime: startTime.toISOString(),
    endTime: endTime.toISOString(),
    startDateStr: startTime.toISOString().split('T')[0],
    endDateStr: endTime.toISOString().split('T')[0]
  }
}));

// 네이버 뉴스 시간 필터링 (전날 06:30 ~ 당일 06:30)
const items = $input.all();
const allNews = [];
const seenUrls = new Set();

for (const item of items) {
  const data = item.json;
  const startTime = new Date(data.startTime);
  const endTime = new Date(data.endTime);
  const newsItems = data.items || [];

  for (const news of newsItems) {
    const pubDate = new Date(news.pubDate);

    // 시간 범위 필터
    if (pubDate >= startTime && pubDate <= endTime) {
      const cleanTitle = (news.title || '').replace(/<[^>]*>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
      const cleanDesc = (news.description || '').replace(/<[^>]*>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
      const url = news.originallink || news.link;

      if (!seenUrls.has(url)) {
        seenUrls.add(url);
        allNews.push({
          json: {
            title: cleanTitle,
            description: cleanDesc,
            link: url,
            originallink: news.originallink,
            pubDate: news.pubDate,
            source: '네이버뉴스'
          }
        });
      }
    }
  }
}

// 최신순 정렬
allNews.sort((a, b) => new Date(b.json.pubDate) - new Date(a.json.pubDate));

if (allNews.length === 0) {
  return [{ json: { title: '', link: '', source: 'naver_empty', noData: true } }];
}

return allNews;

// 키워드 필터링 + 당일 수집 내 중복 제거 (과거 이력 중복은 전체 데이터 통합에서 처리)
const mergedNews = $('뉴스 병합').all();
const naverNews = $('구글시트 네이버뉴스 저장').all();

const allItems = [...mergedNews, ...naverNews];

// 관심 키워드
const includeKeywords = [
  '펀드', '투자신탁', 'ETF', '자산운용', '공모',
  'ISA', 'IRP', '연금저축', '퇴직연금',
  '비과세', '세제', '조세', '과세', '면세', '감면',
  '금융투자', '증권', '자본시장', '금융소비자',
  '금융위', '금감원'
];

// 제외 키워드
const excludeKeywords = [
  '인사', '승진', '임명', '취임', '전보', '이임',
  '채용', '모집', '공모전', '시험', '광고'
];

const filtered = [];
for (const item of allItems) {
  const title = item.json.title || '';
  if (!title || item.json.noData) continue;

  const hasExclude = excludeKeywords.some(kw => title.includes(kw));
  if (hasExclude) continue;

  const hasInclude = includeKeywords.some(kw => title.includes(kw));
  if (hasInclude) {
    filtered.push({
      json: {
        title: title,
        link: item.json.link || item.json.url || item.json.originallink || '',
        pubDate: item.json.pubDate || item.json.isoDate || '',
        source: item.json.source || '기타',
        type: 'news'
      }
    });
  }
}

// 당일 수집 내 제목 기준 중복 제거
const normalize = (t) => t.toLowerCase().replace(/[\s\W]/g, '');
const seen = new Set();
const unique = filtered.filter(item => {
  const key = normalize(item.json.title);
  if (seen.has(key)) return false;
  for (const s of seen) {
    if (key.length > 10 && s.length > 10) {
      if (key.includes(s) || s.includes(key)) return false;
    }
  }
  seen.add(key);
  return true;
});

return unique.slice(0, 15);

// KOFIA 신규펀드 조회 - 지난주 월~일 기간 설정
const now = new Date();
const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));
const dayOfWeek = koreaTime.getDay(); // 0=일, 1=월, ...

// 지난주 월요일 계산
const lastMonday = new Date(koreaTime);
lastMonday.setDate(koreaTime.getDate() - dayOfWeek - 6); // 지난주 월요일
lastMonday.setHours(0, 0, 0, 0);

// 지난주 일요일
const lastSunday = new Date(lastMonday);
lastSunday.setDate(lastMonday.getDate() + 6);
lastSunday.setHours(23, 59, 59, 999);

const formatDate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}${m}${dd}`;
};

const formatDateDash = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
};

return [{
  json: {
    startDate: formatDate(lastMonday),
    endDate: formatDate(lastSunday),
    startDateDash: formatDateDash(lastMonday),
    endDateDash: formatDateDash(lastSunday),
    fundGubun: '1',  // 공모펀드
    type: 'new_fund'
  }
}];

// KOFIA XML 응답 파싱 - 신규펀드 정보 추출
const responseData = $input.first().json.data || $input.first().json;
let xml = '';

if (typeof responseData === 'string') {
  xml = responseData;
} else if (responseData.data) {
  xml = responseData.data;
} else {
  xml = JSON.stringify(responseData);
}

const funds = [];

// XML 파싱 - 각 row에서 펀드 정보 추출
const rowPattern = /<row>(.*?)<\/row>/gs;
let match;

while ((match = rowPattern.exec(xml)) !== null) {
  const row = match[1];

  const getValue = (tag) => {
    const m = new RegExp(`<${tag}><!\\[CDATA\\[(.+?)\\]\\]><\\/${tag}>|<${tag}>(.*?)<\\/${tag}>`).exec(row);
    return m ? (m[1] || m[2] || '').trim() : '';
  };

  const company = getValue('COMPANY_NM') || getValue('COMPANY_CD_NM');
  const fundName = getValue('FUND_NM') || getValue('FUND_NM_KOR');
  const setupDate = getValue('SETUP_DATE') || getValue('EST_DATE');
  const fundType = getValue('FUND_TYPE_NM') || getValue('FUND_TYPE');
  const investRegion = getValue('INVEST_REGION_NM') || getValue('INVEST_REGION');
  const stdCode = getValue('FUND_STD_CD') || getValue('STD_CD');

  if (fundName) {
    funds.push({
      json: {
        company: company,
        fundName: fundName,
        setupDate: setupDate,
        fundType: fundType,
        investRegion: investRegion,
        stdCode: stdCode,
        investStrategy: '',  // 간이투자설명서에서 추출 예정
        type: 'new_fund'
      }
    });
  }
}

// JSON 형태 응답인 경우
if (funds.length === 0) {
  try {
    const jsonData = typeof responseData === 'string' ? JSON.parse(responseData) : responseData;
    const items = jsonData.result || jsonData.data || jsonData.list || [];
    if (Array.isArray(items)) {
      for (const item of items) {
        funds.push({
          json: {
            company: item.COMPANY_NM || item.company || '',
            fundName: item.FUND_NM || item.fundName || '',
            setupDate: item.SETUP_DATE || item.setupDate || '',
            fundType: item.FUND_TYPE_NM || item.fundType || '',
            investRegion: item.INVEST_REGION_NM || item.investRegion || '',
            stdCode: item.FUND_STD_CD || item.stdCode || '',
            investStrategy: '',
            type: 'new_fund'
          }
        });
      }
    }
  } catch(e) { /* not JSON */ }
}

if (funds.length === 0) {
  return [{ json: { noData: true, type: 'new_fund', message: '지난주 신규 공모펀드 없음' } }];
}

return funds;

// 간이투자설명서에서 투자목적 및 투자전략 추출
const responseData = $input.first().json.data || $input.first().json;
const prevData = $('신규펀드 존재?').first().json;
let xml = typeof responseData === 'string' ? responseData : JSON.stringify(responseData);

let investStrategy = '';

// 투자목적/투자전략 필드 추출 시도
const strategyPatterns = [
  /INVEST_PURPOSE[^>]*><!\[CDATA\[(.+?)\]\]>/s,
  /INVEST_STRATEGY[^>]*><!\[CDATA\[(.+?)\]\]>/s,
  /INVEST_PURPOSE[^>]*>(.*?)<\//s,
  /INVEST_STRATEGY[^>]*>(.*?)<\//s,
  /FUND_OBJECT[^>]*><!\[CDATA\[(.+?)\]\]>/s,
  /FUND_OBJECT[^>]*>(.*?)<\//s
];

for (const pattern of strategyPatterns) {
  const m = pattern.exec(xml);
  if (m && (m[1] || m[2])) {
    const text = (m[1] || m[2]).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    if (text.length > 5) {
      investStrategy += (investStrategy ? ' | ' : '') + text;
    }
  }
}

if (investStrategy.length > 500) {
  investStrategy = investStrategy.substring(0, 500) + '...';
}

return [{
  json: {
    ...prevData,
    investStrategy: investStrategy || '정보 없음'
  }
}];

// 3개 소스(정부정책, 뉴스, 신규펀드) 데이터 통합 + 과거 이력 중복제거 + Claude API 요청 생성
const normalize = (t) => t.toLowerCase().replace(/[\s\W]/g, '');

// === 1. 정부정책 데이터 ===
let policyData = { policies: [], count: 0 };
try {
  const policyItems = $('정부정책 중복발송 제거').all();
  if (policyItems.length > 0 && policyItems[0].json.policies) {
    policyData = policyItems[0].json;
  }
} catch(e) {}

// === 2. 뉴스 데이터 ===
let newsList = [];
try {
  const newsItems = $('뉴스 필터링 및 중복제거').all();
  newsList = newsItems.filter(i => i.json.title && !i.json.noData);
} catch(e) {}

// === 3. 신규펀드 데이터 ===
let fundData = [];
try {
  const fundItems = $('구글시트 신규펀드 저장').all();
  fundData = fundItems.filter(i => i.json.펀드명 || i.json.fundName);
} catch(e) {}

// === 4. 과거 이력 기반 뉴스 중복 제거 ===
const pastTitles = [];

// 4-1) 과거 발송 이력 (시트1 요약에서 제목 추출)
try {
  const history = $('과거이력조회').all();
  for (const item of history) {
    const summary = item.json.요약 || '';
    const titleMatches = summary.match(/뉴스 제목\s*:\s*([^(\n]+)/g);
    if (titleMatches) {
      for (const m of titleMatches) {
        const t = m.replace(/뉴스 제목\s*:\s*/, '').trim();
        if (t) pastTitles.push(normalize(t));
      }
    }
  }
} catch(e) {}

// 4-2) 과거 수집된 네이버뉴스
try {
  const pastNews = $('과거 수집뉴스 조회').all();
  for (const item of pastNews) {
    const title = item.json.제목 || item.json.title || '';
    if (title) pastTitles.push(normalize(title));
  }
} catch(e) {}

// 과거 이력 대비 뉴스 중복 필터링
if (pastTitles.length > 0 && newsList.length > 0) {
  newsList = newsList.filter(item => {
    const key = normalize(item.json.title);
    for (const pt of pastTitles) {
      if (!pt || pt.length < 5) continue;
      if (key === pt) return false;
      if (key.length > 15 && pt.length > 15) {
        if (key.includes(pt) || pt.includes(key)) return false;
      }
      const minLen = Math.min(key.length, pt.length);
      const compareLen = Math.floor(minLen * 0.7);
      if (compareLen > 10 && key.substring(0, compareLen) === pt.substring(0, compareLen)) {
        return false;
      }
    }
    return true;
  });
}

// === 데이터 없으면 발송 안함 ===
const totalItems = policyData.count + newsList.length + fundData.length;
if (totalItems === 0) {
  return [{
    json: {
      requestBody: {
        model: "claude-sonnet-4-20250514",
        max_tokens: 1500,
        messages: [{ role: "user", content: "오늘은 수집된 소식이 없습니다. '오늘은 관련 소식이 없습니다'라고 답해주세요." }]
      },
      newsCount: 0, policyCount: 0, fundCount: 0, debug: "전체 데이터 없음"
    }
  }];
}

// === 프롬프트 구성 ===
let policySection = '';
if (policyData.count > 0) {
  policySection = '\n===== 📋 정부시책 (' + policyData.count + '건) =====\n';
  policyData.policies.forEach((p, i) => {
    policySection += (i+1) + '. [금융위원회] ' + p.title + '\n';
    policySection += '   내용: ' + (p.content || '').substring(0, 200) + '\n';
    policySection += '   URL: ' + p.url + '\n\n';
  });
}

let newsSection = '';
if (newsList.length > 0) {
  const finalNews = newsList.slice(0, 10);
  newsSection = '\n===== 📰 뉴스 (' + finalNews.length + '건) =====\n';
  finalNews.forEach((item, idx) => {
    const title = item.json.title || '제목 없음';
    const source = item.json.source || '기타';
    const link = item.json.link || item.json.originallink || '';
    newsSection += (idx+1) + '. [' + source + '] ' + title + '\n   URL: ' + link + '\n\n';
  });
}

let fundSection = '';
if (fundData.length > 0) {
  fundSection = '\n===== 🆕 신규 공모펀드 (' + fundData.length + '건) =====\n';
  fundData.forEach((item, i) => {
    const d = item.json;
    fundSection += (i+1) + '. ' + (d.fundName || d.펀드명) + '\n';
    fundSection += '   운용사: ' + (d.company || d.회사) + '\n';
    fundSection += '   설정일: ' + (d.setupDate || d.설정일) + '\n';
    fundSection += '   유형: ' + (d.fundType || d.펀드유형) + ' | 지역: ' + (d.investRegion || d.투자지역) + '\n';
    fundSection += '   투자전략: ' + (d.investStrategy || d.투자전략 || '정보 없음') + '\n\n';
  });
}

