  return [];
}

const content = inputData.requestBody.messages[0].content;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': process.env.ANTHROPIC_API_KEY || 'YOUR_ANTHROPIC_API_KEY_HERE',
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 3000,
      messages: [{ role: 'user', content: content }]
    },
    json: true
  });

  let aiSummary = '';
  if (response.content && response.content[0] && response.content[0].text) {
    aiSummary = response.content[0].text;
  }

  if (!aiSummary || aiSummary.includes('오늘은 관련 소식이 없습니다')) {
    return [];
  }

  const now = new Date();
  const koreaTime = new Date(now.getTime() + (9 * 60 * 60 * 1000));
  const today = koreaTime.toLocaleDateString('ko-KR', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long'
  });
  const timeString = koreaTime.toLocaleTimeString('ko-KR', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  });

  let message = `📊 ${today}\n`;
  message += `펀드 & 금융정책 모닝 브리핑\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  message += aiSummary;
  message += `\n\n━━━━━━━━━━━━━━━━━━━━\n`;
  message += `⏰ ${timeString} 자동 발송`;

  return [{
    json: {
      text: message,
      aiSummary: aiSummary,
      policyCount: inputData.policyCount,
      fundCount: inputData.fundCount
    }
  }];

} catch (error) {
  return [];
}

